update tax_rate set headline_rate = 1.2, rate_min = 1.2, rate_max = 1.2, threshold_amount = 21330, threshold_note = 'Tax-free allowance per person (double for fiscal partners).', note = 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. Up to and including 2016: a deemed return of 4% of net assets above the allowance, taxed at 30% = 1.2% (Belastingdienst page "Berekenen belasting over vermogen tot en met 2016": https://web.archive.org/web/20161129093530/http://www.belastingdienst.nl:80/wps/wcm/connect/bldcontentnl/belastingdienst/prive/vermogen_en_aanmerkelijk_belang/vermogen/belasting_betalen_over_uw_vermogen/grondslag_sparen_en_beleggen/berekenen_belasting_over_vermogen_tot_en_met_2016). The allowance of €21,330 for 2015 is from the Belastingdienst heffingsvrij-vermogen page (this source).', source_url = 'https://web.archive.org/web/20151220124259/http://www.belastingdienst.nl:80/wps/wcm/connect/bldcontentnl/belastingdienst/prive/vermogen_en_aanmerkelijk_belang/vermogen/belasting_betalen_over_uw_vermogen/heffingsvrij_vermogen/heffingsvrij_vermogen', verified_on = '2015-12-20', next_check_on = '2027-01-15', needs_verification = false, valid_to = '2016-01-01' where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2015-01-01';
insert into tax_rate (jurisdiction_code, tax_type_code, valid_from, valid_to, headline_rate, rate_min, rate_max, threshold_amount, threshold_note, note, source_url, verified_on, next_check_on, needs_verification) select 'NL', 'WEALTH_NET', '2015-01-01', '2016-01-01', 1.2, 1.2, 1.2, 21330, 'Tax-free allowance per person (double for fiscal partners).', 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. Up to and including 2016: a deemed return of 4% of net assets above the allowance, taxed at 30% = 1.2% (Belastingdienst page "Berekenen belasting over vermogen tot en met 2016": https://web.archive.org/web/20161129093530/http://www.belastingdienst.nl:80/wps/wcm/connect/bldcontentnl/belastingdienst/prive/vermogen_en_aanmerkelijk_belang/vermogen/belasting_betalen_over_uw_vermogen/grondslag_sparen_en_beleggen/berekenen_belasting_over_vermogen_tot_en_met_2016). The allowance of €21,330 for 2015 is from the Belastingdienst heffingsvrij-vermogen page (this source).', 'https://web.archive.org/web/20151220124259/http://www.belastingdienst.nl:80/wps/wcm/connect/bldcontentnl/belastingdienst/prive/vermogen_en_aanmerkelijk_belang/vermogen/belasting_betalen_over_uw_vermogen/heffingsvrij_vermogen/heffingsvrij_vermogen', '2015-12-20', '2027-01-15', false where not exists (select 1 from tax_rate where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2015-01-01');
