update tax_rate set headline_rate = 1.2, rate_min = 1.2, rate_max = 1.2, threshold_amount = 24437, threshold_note = 'Tax-free allowance per person (double for fiscal partners).', note = 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. Up to and including 2016: a deemed return of 4% of net assets above the allowance, taxed at 30% = 1.2%. Allowance €24,437 per person (the page''s example: 2 x €24,437 for partners).', source_url = 'https://web.archive.org/web/20161129093530/http://www.belastingdienst.nl:80/wps/wcm/connect/bldcontentnl/belastingdienst/prive/vermogen_en_aanmerkelijk_belang/vermogen/belasting_betalen_over_uw_vermogen/grondslag_sparen_en_beleggen/berekenen_belasting_over_vermogen_tot_en_met_2016', verified_on = '2016-11-29', next_check_on = '2027-01-15', needs_verification = false, valid_to = '2017-01-01' where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2016-01-01';
insert into tax_rate (jurisdiction_code, tax_type_code, valid_from, valid_to, headline_rate, rate_min, rate_max, threshold_amount, threshold_note, note, source_url, verified_on, next_check_on, needs_verification) select 'NL', 'WEALTH_NET', '2016-01-01', '2017-01-01', 1.2, 1.2, 1.2, 24437, 'Tax-free allowance per person (double for fiscal partners).', 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. Up to and including 2016: a deemed return of 4% of net assets above the allowance, taxed at 30% = 1.2%. Allowance €24,437 per person (the page''s example: 2 x €24,437 for partners).', 'https://web.archive.org/web/20161129093530/http://www.belastingdienst.nl:80/wps/wcm/connect/bldcontentnl/belastingdienst/prive/vermogen_en_aanmerkelijk_belang/vermogen/belasting_betalen_over_uw_vermogen/grondslag_sparen_en_beleggen/berekenen_belasting_over_vermogen_tot_en_met_2016', '2016-11-29', '2027-01-15', false where not exists (select 1 from tax_rate where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2016-01-01');
-- NL WEALTH_NET 2017-01-01..2018-01-01 (back-year) ← nl-bd-box3-history
update tax_rate set headline_rate = 1.617, rate_min = 0.861, rate_max = 1.617, threshold_amount = 25000, threshold_note = 'Tax-free allowance per person (double for fiscal partners).', note = 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. NOT ONE RATE: the deemed return rises in 3 bands of the base above the allowance, so one headline rate cannot express it. Stored: headline = the top band (the rate on the part above the last band limit), min = the lowest band. Effective rates (30% x the band''s deemed return): 0.861% up to €75,000, 1.38% from €75,000 to €975,000, 1.617% above €975,000 (limits on the base above the allowance). Applied to all of a portfolio above the allowance, the headline overstates the tax for a base below the top band limit. Belastingdienst table "berekening rendement op vermogen over 2017": band returns 2.871% / 4.600% / 5.39% (savings 1.63%, investments 5.39%). Allowance €25,000 (Belastingdienst, Fiscale informatie 2017: https://web.archive.org/web/20190723195554/https://www.belastingdienst.nl/wps/wcm/connect/bldcontentnl/belastingdienst/prive/aangifte_doen/fiscale_informatie/fiscale_informatie_2017/heffingsvrij-vermogen-box-3-veranderd). The effective rates are derived from the stated percentages.', source_url = 'https://web.archive.org/web/20180308023437/https://www.belastingdienst.nl/wps/wcm/connect/bldcontentnl/belastingdienst/prive/vermogen_en_aanmerkelijk_belang/vermogen/belasting_betalen_over_uw_vermogen/grondslag_sparen_en_beleggen/berekenen_belasting_over_uw_inkomsten_uit_vermogen_vanaf_2017/berekenen_belasting_over_uw_inkomsten_uit_vermogen_vanaf_2017', verified_on = '2018-03-08', next_check_on = '2027-01-15', needs_verification = false, valid_to = '2018-01-01' where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2017-01-01';
insert into tax_rate (jurisdiction_code, tax_type_code, valid_from, valid_to, headline_rate, rate_min, rate_max, threshold_amount, threshold_note, note, source_url, verified_on, next_check_on, needs_verification) select 'NL', 'WEALTH_NET', '2017-01-01', '2018-01-01', 1.617, 0.861, 1.617, 25000, 'Tax-free allowance per person (double for fiscal partners).', 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. NOT ONE RATE: the deemed return rises in 3 bands of the base above the allowance, so one headline rate cannot express it. Stored: headline = the top band (the rate on the part above the last band limit), min = the lowest band. Effective rates (30% x the band''s deemed return): 0.861% up to €75,000, 1.38% from €75,000 to €975,000, 1.617% above €975,000 (limits on the base above the allowance). Applied to all of a portfolio above the allowance, the headline overstates the tax for a base below the top band limit. Belastingdienst table "berekening rendement op vermogen over 2017": band returns 2.871% / 4.600% / 5.39% (savings 1.63%, investments 5.39%). Allowance €25,000 (Belastingdienst, Fiscale informatie 2017: https://web.archive.org/web/20190723195554/https://www.belastingdienst.nl/wps/wcm/connect/bldcontentnl/belastingdienst/prive/aangifte_doen/fiscale_informatie/fiscale_informatie_2017/heffingsvrij-vermogen-box-3-veranderd). The effective rates are derived from the stated percentages.', 'https://web.archive.org/web/20180308023437/https://www.belastingdienst.nl/wps/wcm/connect/bldcontentnl/belastingdienst/prive/vermogen_en_aanmerkelijk_belang/vermogen/belasting_betalen_over_uw_vermogen/grondslag_sparen_en_beleggen/berekenen_belasting_over_uw_inkomsten_uit_vermogen_vanaf_2017/berekenen_belasting_over_uw_inkomsten_uit_vermogen_vanaf_2017', '2018-03-08', '2027-01-15', false where not exists (select 1 from tax_rate where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2017-01-01');
