update tax_rate set headline_rate = 1.614, rate_min = 0.605, rate_max = 1.614, threshold_amount = 30000, threshold_note = 'Tax-free allowance per person (double for fiscal partners).', note = 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. NOT ONE RATE: the deemed return rises in 3 bands of the base above the allowance, so one headline rate cannot express it. Stored: headline = the top band (the rate on the part above the last band limit), min = the lowest band. Effective rates (30% x the band''s deemed return): 0.605% up to €70,800, 1.298% from €70,800 to €978,000, 1.614% above €978,000 (limits on the base above the allowance). Applied to all of a portfolio above the allowance, the headline overstates the tax for a base below the top band limit. Belastingdienst table "berekening rendement op vermogen over 2018": band returns 2.017% / 4.326% / 5.38% (savings 0.36%, investments 5.38%). EY 2018-19 gives the lowest band as 0.6045% (a rounding of the same table). Allowance €30,000 (Belastingdienst, Fiscale informatie 2018: https://web.archive.org/web/20190504211730/https://belastingdienst.nl/wps/wcm/connect/bldcontentnl/belastingdienst/prive/aangifte_doen/fiscale_informatie/fiscale-informatie-2018/heffingsvrij-vermogen-box-3-verandert-in-2018). The effective rates are derived from the stated percentages.', source_url = 'https://web.archive.org/web/20190103155145/https://www.belastingdienst.nl/wps/wcm/connect/bldcontentnl/belastingdienst/prive/vermogen_en_aanmerkelijk_belang/vermogen/belasting_betalen_over_uw_vermogen/grondslag_sparen_en_beleggen/berekening-2018/berekening-belasting-over-inkomen-uit-vermogen-over-2018', verified_on = '2019-01-03', next_check_on = '2027-01-15', needs_verification = false, valid_to = '2019-01-01' where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2018-01-01';
