update tax_rate set headline_rate = 1.677, rate_min = 0.58, rate_max = 1.677, threshold_amount = 30360, threshold_note = 'Tax-free allowance per person (double for fiscal partners).', note = 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. NOT ONE RATE: the deemed return rises in 3 bands of the base above the allowance, so one headline rate cannot express it. Stored: headline = the top band (the rate on the part above the last band limit), min = the lowest band. Effective rates (30% x the band''s deemed return): 0.58% up to €71,650, 1.333% from €71,650 to €989,736, 1.677% above €989,736 (limits on the base above the allowance). Applied to all of a portfolio above the allowance, the headline overstates the tax for a base below the top band limit. Belastingdienst Fiscale informatie 2019, Box 3: savings 0.13% and investments 5.59%, mixed 67/33 in band 1 and 21/79 in band 2. Allowance €30,360 per person; debts count above €3,100. SOURCES DIFFER: the EY Worldwide Personal Tax Guide 2019-20 (content current on 1 July 2019) gives the top band as 5.6% and the burden as 0.5805% to 1.68%; the page of the tax authority itself (stored) gives 5.59%, so 1.677%. The effective rates are derived from the stated percentages.', source_url = 'https://www.belastingdienst.nl/wps/wcm/connect/fisin/fisin2019/belastingberekening', verified_on = '2026-10-03', next_check_on = '2027-01-15', needs_verification = true, valid_to = '2020-01-01' where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2019-01-01';
