update tax_rate set headline_rate = 1.584, rate_min = 0.537, rate_max = 1.584, threshold_amount = 30846, threshold_note = 'Tax-free allowance per person (double for fiscal partners).', note = 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. NOT ONE RATE: the deemed return rises in 3 bands of the base above the allowance, so one headline rate cannot express it. Stored: headline = the top band (the rate on the part above the last band limit), min = the lowest band. Effective rates (30% x the band''s deemed return): 0.537% up to €72,797, 1.256% from €72,797 to €1,005,572, 1.584% above €1,005,572 (limits on the base above the allowance). Applied to all of a portfolio above the allowance, the headline overstates the tax for a base below the top band limit. Belastingdienst Fiscale informatie 2020, Box 3: savings 0.07% and investments 5.28%, mixed 67/33 in band 1 and 21/79 in band 2. Allowance €30,846 per person; debts count above €3,100. SOURCES DIFFER: PwC (income determination, last reviewed 6 Jul 2020) gives deemed returns of 1.80% / 4.22% / 5.33% for 2020; the page of the tax authority itself (stored) gives 5.28% for the top band. The effective rates are derived from the stated percentages.', source_url = 'https://www.belastingdienst.nl/wps/wcm/connect/fisin/fisin2020/belastingberekening', verified_on = '2026-10-03', next_check_on = '2027-01-15', needs_verification = true, valid_to = '2021-01-01' where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2020-01-01';
insert into tax_rate (jurisdiction_code, tax_type_code, valid_from, valid_to, headline_rate, rate_min, rate_max, threshold_amount, threshold_note, note, source_url, verified_on, next_check_on, needs_verification) select 'NL', 'WEALTH_NET', '2020-01-01', '2021-01-01', 1.584, 0.537, 1.584, 30846, 'Tax-free allowance per person (double for fiscal partners).', 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. NOT ONE RATE: the deemed return rises in 3 bands of the base above the allowance, so one headline rate cannot express it. Stored: headline = the top band (the rate on the part above the last band limit), min = the lowest band. Effective rates (30% x the band''s deemed return): 0.537% up to €72,797, 1.256% from €72,797 to €1,005,572, 1.584% above €1,005,572 (limits on the base above the allowance). Applied to all of a portfolio above the allowance, the headline overstates the tax for a base below the top band limit. Belastingdienst Fiscale informatie 2020, Box 3: savings 0.07% and investments 5.28%, mixed 67/33 in band 1 and 21/79 in band 2. Allowance €30,846 per person; debts count above €3,100. SOURCES DIFFER: PwC (income determination, last reviewed 6 Jul 2020) gives deemed returns of 1.80% / 4.22% / 5.33% for 2020; the page of the tax authority itself (stored) gives 5.28% for the top band. The effective rates are derived from the stated percentages.', 'https://www.belastingdienst.nl/wps/wcm/connect/fisin/fisin2020/belastingberekening', '2026-10-03', '2027-01-15', true where not exists (select 1 from tax_rate where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2020-01-01');
-- NL WEALTH_NET 2021-01-01..2022-01-01 (back-year) ← nl-bd-box3
update tax_rate set headline_rate = 1.764, rate_min = 0.588, rate_max = 1.764, threshold_amount = 50000, threshold_note = 'Tax-free allowance per person (double for fiscal partners).', note = 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. NOT ONE RATE: the deemed return rises in 3 bands of the base above the allowance, so one headline rate cannot express it. Stored: headline = the top band (the rate on the part above the last band limit), min = the lowest band. Effective rates (31% x the band''s deemed return): 0.588% up to €50,000, 1.395% from €50,000 to €950,000, 1.764% above €950,000 (limits on the base above the allowance). Applied to all of a portfolio above the allowance, the headline overstates the tax for a base below the top band limit. TWO METHODS for 2021, the more favourable one applies (Belastingdienst, berekening box 3-inkomen 2021, the newest page): (a) the old bands (Fiscale informatie 2021: savings 0.03% and investments 5.69%, mixed 67/33 and 21/79: https://www.belastingdienst.nl/wps/wcm/connect/fisin/fisin2021/belastingberekening); (b) actual holdings: investments 5.69%, bank balances 0.01%, debts 2.46%, so 1.764% on investments. For a portfolio of investments only, (a) is the lower. Allowance €50,000 per person; debts count above €3,200. The effective rates are derived from the stated percentages.', source_url = 'https://www.belastingdienst.nl/wps/wcm/connect/nl/box-3/content/berekening-box-3-inkomen-2021', verified_on = '2026-10-03', next_check_on = '2027-01-15', needs_verification = false, valid_to = '2022-01-01' where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2021-01-01';
insert into tax_rate (jurisdiction_code, tax_type_code, valid_from, valid_to, headline_rate, rate_min, rate_max, threshold_amount, threshold_note, note, source_url, verified_on, next_check_on, needs_verification) select 'NL', 'WEALTH_NET', '2021-01-01', '2022-01-01', 1.764, 0.588, 1.764, 50000, 'Tax-free allowance per person (double for fiscal partners).', 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. NOT ONE RATE: the deemed return rises in 3 bands of the base above the allowance, so one headline rate cannot express it. Stored: headline = the top band (the rate on the part above the last band limit), min = the lowest band. Effective rates (31% x the band''s deemed return): 0.588% up to €50,000, 1.395% from €50,000 to €950,000, 1.764% above €950,000 (limits on the base above the allowance). Applied to all of a portfolio above the allowance, the headline overstates the tax for a base below the top band limit. TWO METHODS for 2021, the more favourable one applies (Belastingdienst, berekening box 3-inkomen 2021, the newest page): (a) the old bands (Fiscale informatie 2021: savings 0.03% and investments 5.69%, mixed 67/33 and 21/79: https://www.belastingdienst.nl/wps/wcm/connect/fisin/fisin2021/belastingberekening); (b) actual holdings: investments 5.69%, bank balances 0.01%, debts 2.46%, so 1.764% on investments. For a portfolio of investments only, (a) is the lower. Allowance €50,000 per person; debts count above €3,200. The effective rates are derived from the stated percentages.', 'https://www.belastingdienst.nl/wps/wcm/connect/nl/box-3/content/berekening-box-3-inkomen-2021', '2026-10-03', '2027-01-15', false where not exists (select 1 from tax_rate where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2021-01-01');
