-- NL WEALTH_NET 2023-01-01..2024-01-01 (back-year) ← nl-bd-box3
update tax_rate set headline_rate = 1.974, rate_min = 0.294, rate_max = 1.974, threshold_amount = 57000, threshold_note = 'Tax-free allowance per person (double for fiscal partners); debts count above €3,400 per person.', note = 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. Effective rate = 32% x the deemed return: 1.974% of net assets above the allowance on investments and other assets (32% x 6.17%), 0.294% on bank balances (32% x 0.92%). Debts are deducted at 2.46%. From 2023 only this method applies (the page says the old method no longer does). The effective rates are derived from the stated percentages.', source_url = 'https://www.belastingdienst.nl/wps/wcm/connect/nl/box-3/content/berekening-box-3-inkomen-2023', verified_on = '2026-10-03', next_check_on = '2027-01-15', needs_verification = false, valid_to = '2024-01-01' where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2023-01-01';
insert into tax_rate (jurisdiction_code, tax_type_code, valid_from, valid_to, headline_rate, rate_min, rate_max, threshold_amount, threshold_note, note, source_url, verified_on, next_check_on, needs_verification) select 'NL', 'WEALTH_NET', '2023-01-01', '2024-01-01', 1.974, 0.294, 1.974, 57000, 'Tax-free allowance per person (double for fiscal partners); debts count above €3,400 per person.', 'Box 3 is an income tax on a deemed return, not a wealth tax in name, and it works as one. Effective rate = 32% x the deemed return: 1.974% of net assets above the allowance on investments and other assets (32% x 6.17%), 0.294% on bank balances (32% x 0.92%). Debts are deducted at 2.46%. From 2023 only this method applies (the page says the old method no longer does). The effective rates are derived from the stated percentages.', 'https://www.belastingdienst.nl/wps/wcm/connect/nl/box-3/content/berekening-box-3-inkomen-2023', '2026-10-03', '2027-01-15', false where not exists (select 1 from tax_rate where jurisdiction_code = 'NL' and tax_type_code = 'WEALTH_NET' and valid_from = '2023-01-01');
